import React, { useState, useEffect } from 'react';

interface ScarewarePersistenceProps {
  onEscape: () => void;
  onLearnMore: () => void;
}

const ScarewarePersistence: React.FC<ScarewarePersistenceProps> = ({ onEscape, onLearnMore }) => {
  const [layerCount, setLayerCount] = useState(0);
  const [blockedAttempts, setBlockedAttempts] = useState(0);

  useEffect(() => {
    // Real scareware technique: Force fullscreen mode
    const forceFullscreen = async () => {
      try {
        if (document.documentElement.requestFullscreen) {
          await document.documentElement.requestFullscreen();
        } else if ((document.documentElement as any).webkitRequestFullscreen) {
          await (document.documentElement as any).webkitRequestFullscreen();
        } else if ((document.documentElement as any).mozRequestFullScreen) {
          await (document.documentElement as any).mozRequestFullScreen();
        } else if ((document.documentElement as any).msRequestFullscreen) {
          await (document.documentElement as any).msRequestFullscreen();
        }
      } catch (error) {
        console.log('Fullscreen request failed:', error);
      }
    };

    // Real scareware technique: Prevent exiting fullscreen
    const preventFullscreenExit = () => {
      if (!document.fullscreenElement && 
          !(document as any).webkitFullscreenElement && 
          !(document as any).mozFullScreenElement && 
          !(document as any).msFullscreenElement) {
        // User exited fullscreen, force it back
        setTimeout(forceFullscreen, 100);
      }
    };

    // Real scareware technique: Create multiple overlay layers
    const addLayer = () => {
      if (layerCount < 5) {
        setLayerCount(prev => prev + 1);
        setTimeout(addLayer, 2000);
      }
    };

    // Start the attack sequence
    setTimeout(() => {
      forceFullscreen();
      addLayer();
    }, 1000);

    // Real scareware technique: Prevent all escape methods
    const preventEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape' || e.key === 'F11' || e.key === 'F5') {
        e.preventDefault();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    const preventAltF4 = (e: KeyboardEvent) => {
      if (e.altKey && e.key === 'F4') {
        e.preventDefault();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    const preventCtrlW = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.key === 'w') {
        e.preventDefault();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    const preventAltTab = (e: KeyboardEvent) => {
      if (e.altKey && e.key === 'Tab') {
        e.preventDefault();
        setBlockedAttempts(prev => prev + 1);
        return false;
      }
    };

    // Real scareware technique: Prevent right-click context menu
    const preventRightClick = (e: MouseEvent) => {
      e.preventDefault();
      setBlockedAttempts(prev => prev + 1);
      return false;
    };

    // Real scareware technique: Prevent window focus loss
    const preventBlur = () => {
      window.focus();
      setBlockedAttempts(prev => prev + 1);
    };

    // Add all event listeners
    document.addEventListener('keydown', preventEscape);
    document.addEventListener('keydown', preventAltF4);
    document.addEventListener('keydown', preventCtrlW);
    document.addEventListener('keydown', preventAltTab);
    document.addEventListener('contextmenu', preventRightClick);
    window.addEventListener('blur', preventBlur);

    // Monitor fullscreen state and prevent exit
    document.addEventListener('fullscreenchange', preventFullscreenExit);
    document.addEventListener('webkitfullscreenchange', preventFullscreenExit);
    document.addEventListener('mozfullscreenchange', preventFullscreenExit);
    document.addEventListener('MSFullscreenChange', preventFullscreenExit);

    // Real scareware technique: Change document title to create urgency
    const originalTitle = document.title;
    document.title = '🚨 CRITICAL SYSTEM ALERT 🚨';

    // Real scareware technique: Prevent tab switching
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {
        document.title = '⚠️ RETURN IMMEDIATELY - SYSTEM COMPROMISED ⚠️';
        setTimeout(() => {
          if (document.hidden) {
            document.title = '🚨 YOUR COMPUTER IS BEING HACKED 🚨';
          }
        }, 1000);
      }
    });

    return () => {
      document.removeEventListener('keydown', preventEscape);
      document.removeEventListener('keydown', preventAltF4);
      document.removeEventListener('keydown', preventCtrlW);
      document.removeEventListener('keydown', preventAltTab);
      document.removeEventListener('contextmenu', preventRightClick);
      window.removeEventListener('blur', preventBlur);
      document.removeEventListener('fullscreenchange', preventFullscreenExit);
      document.removeEventListener('webkitfullscreenchange', preventFullscreenExit);
      document.removeEventListener('mozfullscreenchange', preventFullscreenExit);
      document.removeEventListener('MSFullscreenChange', preventFullscreenExit);
      document.title = originalTitle;
      
      // Exit fullscreen when component unmounts
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else if ((document as any).webkitFullscreenElement) {
        (document as any).webkitExitFullscreen();
      } else if ((document as any).mozFullScreenElement) {
        (document as any).mozCancelFullScreen();
      } else if ((document as any).msFullscreenElement) {
        (document as any).msExitFullscreen();
      }
    };
  }, [layerCount]);

  const handleEscape = () => {
    onEscape();
  };

  const handleLearnMore = () => {
    onLearnMore();
  };

  return (
    <>
      {/* Multiple overlay layers - real scareware technique */}
      {Array.from({ length: layerCount }, (_, index) => (
        <div
          key={index}
          style={{
            position: 'fixed',
            top: 0,
