                marginBottom: '2rem'
              }}>
                <div style={{ fontSize: '1.1rem', marginBottom: '1rem' }}>
                  <strong>IMMEDIATE ACTION REQUIRED:</strong>
                </div>
                <div style={{ fontSize: '1rem' }}>
                  Call: 1-800-FAKE-SUPPORT
                  <br />
                  Or pay: $99.99 for immediate protection
                </div>
              </div>

              <div style={{ 
                background: 'rgba(255, 255, 255, 0.3)', 
                padding: '1rem', 
                borderRadius: '8px',
                marginBottom: '2rem',
                fontSize: '0.9rem'
              }}>
                <strong>SIMULATION MODE:</strong> This demonstrates real scareware persistence.
                <br />
                <strong>Blocked escape attempts: {blockedAttempts}</strong>
                <br />
                <strong>Overlay layers: {layerCount}</strong>
              </div>

              <div style={{ marginTop: '2rem' }}>
                <button 
                  className="button button-success" 
                  onClick={handleEscape}
                  style={{ 
                    fontSize: '1.2rem', 
                    padding: '1rem 2rem', 
                    marginRight: '1rem',
                    background: '#28a745',
                    border: '3px solid #fff',
                    boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
                  }}
                >
                  🚪 Emergency Escape (Simulation)
                </button>
                <button 
                  className="button button-primary" 
                  onClick={handleLearnMore}
                  style={{ 
                    fontSize: '1.2rem', 
                    padding: '1rem 2rem',
                    background: '#007bff',
                    border: '3px solid #fff',
                    boxShadow: '0 4px 8px rgba(0,0,0,0.3)'
                  }}
                >
                  📚 Learn More
                </button>
              </div>
            </div>
          )}
        </div>
      ))}

      {/* Persistent popup that keeps appearing */}
      <div 
        style={{
          position: 'fixed',
          top: '20px',
          right: '20px',
          background: 'white',
          border: '3px solid #ff0000',
          borderRadius: '8px',
          padding: '1rem',
          zIndex: 20000,
          boxShadow: '0 8px 32px rgba(0,0,0,0.5)',
          animation: 'shake 0.5s infinite'
        }}
      >
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>⚠️</div>
          <div style={{ fontWeight: 'bold', color: '#ff0000', marginBottom: '0.5rem' }}>
            URGENT ALERT!
          </div>
          <div style={{ fontSize: '0.8rem', marginBottom: '1rem' }}>
            System compromised!
            <br />
            <strong>SIMULATION MODE</strong>
          </div>
          <button 
            onClick={handleEscape}
            style={{
              background: '#ff0000',
              color: 'white',
              border: 'none',
              padding: '0.5rem 1rem',
              borderRadius: '4px',
              cursor: 'pointer'
